DECLARE
    l_base TIMESTAMP := CAST(TRUNC(SYS_EXTRACT_UTC(SYSTIMESTAMP)) AS TIMESTAMP);
    l_ahora TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);
    l_id NUMBER;
    l_ts TIMESTAMP;
    -- 'b': segundos desde la medianoche UTC de hoy (negativo = días atrás); 'n': segundos antes de ahora.
    FUNCTION t(p_clase VARCHAR2, p_seg NUMBER) RETURN TIMESTAMP IS
    BEGIN
        IF p_clase = 'n' THEN RETURN l_ahora - NUMTODSINTERVAL(p_seg, 'SECOND'); END IF;
        RETURN l_base + NUMTODSINTERVAL(p_seg, 'SECOND');
    END;
    FUNCTION ms(p_ts TIMESTAMP) RETURN NUMBER IS
    BEGIN
        RETURN ROUND((CAST(p_ts AS DATE) - DATE '1970-01-01') * 86400 * 1000);
    END;
    PROCEDURE lec(p_dev VARCHAR2, p_seq NUMBER, p_sku VARCHAR2, p_cant NUMBER, p_oper VARCHAR2,
                  p_nota VARCHAR2, p_dan NUMBER, p_ts TIMESTAMP, p_vig CHAR, p_recv TIMESTAMP) IS
        l_raw VARCHAR2(4000);
    BEGIN
        l_raw := 'REC|' || p_seq || '|' || ms(p_ts) || '|ACTUAL|' || p_sku || '|' || p_cant || '|' || p_oper
                 || '|' || p_nota || '|' || p_dan;
        INSERT INTO captura_transito (uuid_dispositivo, seq, datos_raw, estado, fecha_recepcion)
        VALUES (p_dev, p_seq, l_raw, 'PROCESADO', p_recv) RETURNING id_transito INTO l_id;
        INSERT INTO registros_procesados (id_transito, id_conteo, sku, cantidad, operador, nota, fecha_captura,
                                          vigente, fecha_procesado, danados)
        VALUES (l_id, 'ACTUAL', p_sku, p_cant, p_oper, p_nota, p_ts, p_vig, p_recv + NUMTODSINTERVAL(40, 'SECOND'), p_dan);
    END;
    PROCEDURE cruda(p_dev VARCHAR2, p_seq NUMBER, p_ts TIMESTAMP, p_resto VARCHAR2, p_estado VARCHAR2,
                    p_msg VARCHAR2, p_recv TIMESTAMP) IS
        l_raw VARCHAR2(4000);
    BEGIN
        l_raw := 'REC|' || p_seq || '|' || ms(p_ts) || '|' || p_resto;
        INSERT INTO captura_transito (uuid_dispositivo, seq, datos_raw, estado, mensaje_error, fecha_recepcion)
        VALUES (p_dev, p_seq, l_raw, p_estado, p_msg, p_recv);
    END;
    PROCEDURE ses(p_dev VARCHAR2, p_ini TIMESTAMP, p_n NUMBER, p_proc NUMBER, p_err NUMBER, p_origen VARCHAR2) IS
        l_fin TIMESTAMP := p_ini + NUMTODSINTERVAL(15 + p_n, 'SECOND');
    BEGIN
        INSERT INTO sync_sesiones (uuid_dispositivo, inicio, fin, recibidos, aceptados)
        VALUES (p_dev, p_ini, l_fin, p_n, p_n);
        INSERT INTO log_batch (inicio, fin, procesados, errores, origen)
        VALUES (l_fin + NUMTODSINTERVAL(20, 'SECOND'), l_fin + NUMTODSINTERVAL(24, 'SECOND'), p_proc, p_err, p_origen);
    END;
